import requests

def check_subdomains(domain, subdomains):
    for sub in subdomains:
        url = f'http://{sub}.{domain}'
        try:
            res = requests.get(url, timeout=2)
            if res.status_code == 200:
                print(f'[+] Found Subdomain: {url}')
        except requests.ConnectionError:
            pass

sub_list = ['admin', 'mail', 'test', 'dev', 'api']
check_subdomains('example.com', sub_list)

import requests

def test_xss(url):
    payload = '<script>alert("XSS")</script>'
    target_url = f'{url}?q={payload}'
    response = requests.get(target_url)
    if payload in response.text:
        print('[!] Vulnerable to Reflected XSS!')
    else:
        print('[-] Safe from basic XSS.')

test_xss('http://example.com/search')

import hashlib

def crack_md5(target_hash, wordlist_file):
    try:
        with open(wordlist_file, 'r') as file:
            for word in file.readlines():
                word = word.strip()
                if hashlib.md5(word.encode()).hexdigest() == target_hash:
                    print(f'[+] Hash Cracked! Password is: {word}')
                    return word
        print('[-] Password not found in wordlist.')
    except FileNotFoundError:
        print('[!] Wordlist file not found.')

