import requests

def audit_headers(url):
    res = requests.get(url)
    headers = res.headers
    sec_headers = ['Content-Security-Policy', 'Strict-Transport-Security', 'X-Frame-Options', 'X-Content-Type-Options']

    print(f'Audit Report for {url}:')
    for h in sec_headers:
        if h in headers:
            print(f'[✔] {h}: Present')
        else:
            print(f'[✘] {h}: MISSING!')

audit_headers('https://google.com')
